// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }
    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        amount = bound(amount, 0, address(this).balance);
        vm.deal(actor, amount);
        vm.prank(actor);
        c.addToBalance{value: amount}();
        vm.prank(actor);
        c.withdrawBalance();
        assertTrue(c.getBalance(actor) == 0);
    }
}
